import { createBatchedStore, createSessionId, defineEvent, defineTrace, } from '@sanity/telemetry';
import { createTelemetryIntake, _resolveTelemetryEnvironment, isTelemetryEnvDenied, noopTelemetry, } from '@sanity/workflow-engine';
export const WorkflowCliCommandExecuted = defineTrace({
    name: 'Workflows CLI Command Executed',
    version: 2,
    description: 'A Workflows CLI command was executed — the trace context carries the command path and each flag used in canonical long form (an option flag as `--name=value`, a boolean as `--name` or `--no-name`, a redacted or undeclared flag as its name only), and the payload carries a success flag',
});
export const WorkflowDefinitionShared = defineEvent({
    name: 'Workflows CLI Definition Shared',
    version: 1,
    description: 'A newly created workflow definition version was donated to Sanity. Content-free marker: the content hash plus the same structural counts Workflows Engine Definition Deployed carries — the document itself goes to the first-party definition-feedback endpoint, never through telemetry.',
});
export const WorkflowDefinitionSharingDecided = defineEvent({
    name: 'Workflows CLI Definition Sharing Decided',
    version: 2,
    description: 'One per deploy invocation that created new definition versions: whether donation followed the default or an explicit flag, whether anything reached the endpoint, and how many versions were eligible. Content-free — measures the true opt-out rate without ever carrying the document.',
});
const OFF = { kind: 'off', logger: noopTelemetry };
let session;
export function cliTelemetry() {
    return session?.telemetry ?? OFF;
}
export function setCliTelemetry(telemetry, context) {
    const trace = telemetry.kind === 'builtin'
        ? telemetry.store.logger.trace(WorkflowCliCommandExecuted, context)
        : undefined;
    trace?.start();
    session = { telemetry, context, trace };
}
export function clearCliTelemetry() {
    session = undefined;
}
export function createBuiltinTelemetry(args) {
    const { client, projectId, env, forceSend = false, packageVersion } = args;
    const envDenied = isTelemetryEnvDenied(env);
    const store = createBatchedStore(createSessionId(), createTelemetryIntake({
        client,
        projectId: projectId ?? '',
        denied: forceSend ? false : envDenied,
        context: {
            surface: 'cli',
            environment: _resolveTelemetryEnvironment(env.NODE_ENV, 'production'),
            ...(packageVersion !== undefined ? { packageVersion } : {}),
        },
    }));
    return { kind: 'builtin', logger: store.logger, store, envDenied, forceSend };
}
function traceAsLogEvent(trace) {
    const { name, version, description } = trace;
    return { type: 'log', name, version, description };
}
const FLUSH_DEADLINE_MS = 3_000;
export async function raceWithDeadline(work, deadlineMs) {
    let deadline;
    try {
        return await Promise.race([
            work,
            new Promise((resolve) => {
                deadline = setTimeout(() => resolve(undefined), deadlineMs);
            }),
        ]);
    }
    finally {
        clearTimeout(deadline);
    }
}
export async function finishCliTelemetry(result) {
    if (session === undefined)
        return;
    const { telemetry, context, trace } = session;
    if (telemetry.kind === 'provided') {
        telemetry.logger.log(traceAsLogEvent(WorkflowCliCommandExecuted), {
            ...context,
            ...result,
        });
        return;
    }
    if (trace !== undefined) {
        trace.log(result);
        trace.complete();
        session = { ...session, trace: undefined };
    }
    const { store } = telemetry;
    try {
        await raceWithDeadline(store.flush(), FLUSH_DEADLINE_MS);
    }
    finally {
        store.end();
    }
}
